begin;
create extension if not exists pgtap with schema extensions;
select plan(16);
insert into public.orgs(id,name,slug) values('a1000000-0000-4000-8000-000000000001','Meeting recovery test','meeting-recovery-test');
insert into auth.users(id) values('a2000000-0000-4000-8000-000000000001');
insert into public.accounts(id,org_id,auth_user_id) values('a3000000-0000-4000-8000-000000000001','a1000000-0000-4000-8000-000000000001','a2000000-0000-4000-8000-000000000001');
insert into public.profiles(id,org_id,account_id,kind,display_name,avatar_source,timezone) values('a4000000-0000-4000-8000-000000000001','a1000000-0000-4000-8000-000000000001','a3000000-0000-4000-8000-000000000001','educator','Synthetic teacher','seed','UTC');
insert into public.channels(id,org_id,kind,topic,visibility,purpose) values('a5000000-0000-4000-8000-000000000001','a1000000-0000-4000-8000-000000000001','channel','Synthetic class','private','learning-space');
insert into public.channel_live_sessions(id,org_id,channel_id,provider,status,session_scope_key,started_by_profile_id,join_path) values('a6000000-0000-4000-8000-000000000001','a1000000-0000-4000-8000-000000000001','a5000000-0000-4000-8000-000000000001','zoom','live','recovery-test','a4000000-0000-4000-8000-000000000001','/live/test');
insert into public.live_session_browser_links(token_hash,live_session_id,purpose,auth_user_id,expires_at) values(repeat('a',64),'a6000000-0000-4000-8000-000000000001','handoff','a2000000-0000-4000-8000-000000000001',now()+interval '1 minute');
select ok(public.redeem_meeting_browser_handoff(repeat('a',64),'a6000000-0000-4000-8000-000000000001',repeat('b',64),repeat('c',64)),'first redemption succeeds');
select ok(public.redeem_meeting_browser_handoff(repeat('a',64),'a6000000-0000-4000-8000-000000000001',repeat('b',64),repeat('c',64)),'lost response retries safely');
select is((select count(*)::int from public.live_session_browser_links where token_hash=repeat('c',64)),1,'retry creates exactly one access credential');
select ok(not public.redeem_meeting_browser_handoff(repeat('a',64),'a6000000-0000-4000-8000-000000000001',repeat('d',64),repeat('e',64)),'different browser cannot redeem');
select ok(not public.redeem_meeting_browser_handoff(repeat('a',64),'a6000000-0000-4000-8000-000000000009',repeat('b',64),repeat('c',64)),'wrong session cannot redeem');
update public.live_session_browser_links set expires_at=now()-interval '1 second' where token_hash=repeat('a',64);
select ok(not public.redeem_meeting_browser_handoff(repeat('a',64),'a6000000-0000-4000-8000-000000000001',repeat('b',64),repeat('c',64)),'expired handoff cannot retry');
insert into public.live_session_browser_links(token_hash,live_session_id,purpose,auth_user_id,expires_at) values(repeat('d',64),'a6000000-0000-4000-8000-000000000001','handoff','a2000000-0000-4000-8000-000000000001',now()+interval '1 minute');
select throws_ok($$select public.redeem_meeting_browser_handoff(repeat('d',64),'a6000000-0000-4000-8000-000000000001',repeat('e',64),repeat('c',64))$$,'23505',null,'failed access insertion rolls back');
select is((select redemption_hash from public.live_session_browser_links where token_hash=repeat('d',64)),null,'failed transaction does not bind or consume handoff');
select ok(public.redeem_meeting_browser_handoff(repeat('d',64),'a6000000-0000-4000-8000-000000000001',repeat('e',64),repeat('f',64)),'retry after database failure succeeds');
select is(public.request_meeting_admission('a6000000-0000-4000-8000-000000000001',repeat('f',64),'identity','Guest'),'waiting','new guest waits');
update public.live_session_admissions set status='approved' where token_hash=repeat('f',64);
select is(public.request_meeting_admission('a6000000-0000-4000-8000-000000000001',repeat('f',64),'identity','Guest'),'approved','approved guest is admitted');
select is(public.request_meeting_admission('a6000000-0000-4000-8000-000000000001',repeat('f',64),'different-identity','Guest'),'denied','approval cannot transfer identities');
update public.live_session_admissions set status='denied' where token_hash=repeat('f',64);
select is(public.request_meeting_admission('a6000000-0000-4000-8000-000000000001',repeat('f',64),'identity','Guest'),'denied','retry cannot overwrite denial');
update public.channel_live_sessions set status='ended' where id='a6000000-0000-4000-8000-000000000001';
select is(public.request_meeting_admission('a6000000-0000-4000-8000-000000000001',repeat('f',64),'identity','Guest'),'ended','ended session cannot admit');
select ok(not has_function_privilege('anon','public.redeem_meeting_browser_handoff(text,uuid,text,text)','execute'),'anonymous cannot invoke redemption RPC');
select ok(not has_table_privilege('authenticated','public.live_session_admissions','select'),'frontend cannot read waiting identities');
select * from finish();
rollback;
